$categories=['surat_pengantar'=>'Surat Pengantar','surat_keterangan'=>'Surat Keterangan','dokumen_warga'=>'Dokumen Warga','laporan'=>'Laporan','dokumen_kegiatan'=>'Dokumen Kegiatan','lainnya'=>'Lainnya'];
?>
