<div class="row g-4"><div class="col-xl-4"><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Unggah Dokumen</h2></div><div class="panel-card-body"><form method="post" action="index.php" enctype="multipart/form-data" class="vstack gap-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="upload_arsip"><input type="hidden" name="return_page" value="arsip"><div><label class="form-label">Judul dokumen</label><input class="form-control" name="judul" required></div><div><label class="form-label">Kategori</label><select class="form-select" name="kategori"><?php foreach($categories as $v=>$label): ?><option value="<?= $v ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div><label class="form-label">Tanggal dokumen</label><input class="form-control" type="date" name="tanggal_dokumen"></div><div><label class="form-label">Deskripsi</label><textarea class="form-control" name="deskripsi" rows="3"></textarea></div><div><label class="form-label">Akses dokumen</label><select class="form-select" name="akses"><option value="admin_pengurus">Admin & Pengurus</option><option value="semua_pengguna">Semua pengguna</option></select></div><div><label class="form-label">Pilih file</label><input class="form-control" type="file" name="file" accept=".pdf,.jpg,.jpeg,.png" required><div class="form-text">PDF/JPG/PNG maksimal 5 MB.</div></div><button class="btn btn-army"><i class="bi bi-cloud-arrow-up me-2"></i>Unggah Arsip</button></form></div></section></div><div class="col-xl-8"><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Daftar Arsip</h2><span class="text-muted-2 small"><?= count($rows) ?> dokumen</span></div><div class="panel-card-body"><?php if(!$rows): ?><div class="empty-state"><i class="bi bi-folder2-open"></i><strong>Belum ada dokumen arsip</strong><span>Dokumen yang diunggah akan tersimpan di sini.</span></div><?php else: foreach($rows as $a): ?><div class="d-flex align-items-center gap-3 py-3 border-bottom"><div class="quick-action-icon"><i class="bi bi-file-earmark-text"></i></div><div class="flex-grow-1 min-w-0"><strong class="d-block text-truncate"><?= e($a['judul']) ?></strong><small class="text-muted-2"><?= e($categories[$a['kategori']]??'Lainnya') ?> · <?= e(number_format(($a['ukuran_byte']??0)/1024,1)) ?> KB · <?= e(format_date($a['tanggal_dokumen']??$a['created_at'])) ?></small><small class="d-block text-muted-2">Akses: <?= $a['akses']==='semua_pengguna'?'Semua pengguna':'Admin & Pengurus' ?></small></div><div class="d-flex flex-column flex-sm-row gap-2"><a class="btn btn-sm btn-outline-army" href="index.php?action=download_arsip&id=<?= (int)$a['id'] ?>"><i class="bi bi-download"></i><span class="d-none d-sm-inline ms-1">Unduh</span></a><form method="post" action="index.php" class="m-0"><?= csrf_field() ?><input type="hidden" name="action" value="delete_arsip"><input type="hidden" name="return_page" value="arsip"><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Hapus dokumen ini?"><i class="bi bi-trash"></i></button></form></div></div><?php endforeach; endif; ?></div></section></div></div>
